export const formatMalaysiaDateTime = (instant: Date | string): string => {
  const c = malaysiaWallClock(instant);
  return `${c.day} ${monthName(c.month)} ${pad(c.year, 4)}, ${pad(c.hour)}:${pad(c.minute)}`;
