export const formatCalendarDate = (date: string | Date): string => {
  const iso = typeof date === "string" ? date : calendarDateFromDb(date);
  if (!isCalendarDate(iso)) {
    throw new Error(`Not a valid YYYY-MM-DD date: ${String(date)}`);
