/**
 * Half-open instant range [start, endExclusive) covering Malaysia months
 * from..to inclusive — the WHERE clause of the collections report.
 */
export const malaysiaMonthRange = (from: string, to: string): { start: Date; endExclusive: Date } => {
  const months = monthsBetween(from, to);
  const { year, month } = parseYearMonth(months[months.length - 1] ?? to);
  const next = month === 12 ? formatYearMonth(year + 1, 1) : formatYearMonth(year, month + 1);
  return { start: malaysiaMonthStart(from), endExclusive: malaysiaMonthStart(next) };
};

