import { afterAll, describe, expect, it } from "vitest";

import { generateSchedule, invoiceStatus, parseRinggitToSen, ScheduledInvoice } from "./billing";

type Lease = Parameters<typeof generateSchedule>[0];

const ORIGINAL_TZ = process.env.TZ;

const rent = (schedule: ScheduledInvoice[]) => schedule.filter((invoice) => invoice.kind === "rent");

const rentRows = (lease: Lease) =>
  rent(generateSchedule(lease)).map(({ periodStart, periodEnd, dueDate, amountSen }) => [
    periodStart,
    periodEnd,
    dueDate,
    amountSen,
  ]);

const lease = (startDate: string, endDate: string, monthlyRentSen = 100_000, depositSen = 0): Lease => ({
  startDate,
  endDate,
  monthlyRentSen,
  depositSen,
});

afterAll(() => {
  process.env.TZ = ORIGINAL_TZ;
});

describe("test environment", () => {
  it("runs under the TZ given on the command line", () => {
    const resolved = Intl.DateTimeFormat().resolvedOptions().timeZone;
    console.info(`TZ=${process.env.TZ ?? "(unset)"} resolved=${resolved} offset(1970)=${new Date(0).getTimezoneOffset()}`);
    if (process.env.TZ) {
      expect(resolved).toBe(process.env.TZ);
    }
  });
});

describe("generateSchedule", () => {
  it("reproduces the brief's worked example (Aisyah) exactly", () => {
    expect(
      generateSchedule({
        startDate: "2026-01-31",
        endDate: "2026-07-15",
        monthlyRentSen: 150_000,
        depositSen: 300_000,
      }),
    ).toEqual([
      { kind: "deposit", periodIndex: null, periodStart: null, periodEnd: null, dueDate: "2026-01-31", amountSen: 300_000 },
      { kind: "rent", periodIndex: 0, periodStart: "2026-01-31", periodEnd: "2026-02-27", dueDate: "2026-01-31", amountSen: 150_000 },
      { kind: "rent", periodIndex: 1, periodStart: "2026-02-28", periodEnd: "2026-03-30", dueDate: "2026-02-28", amountSen: 150_000 },
      { kind: "rent", periodIndex: 2, periodStart: "2026-03-31", periodEnd: "2026-04-29", dueDate: "2026-03-31", amountSen: 150_000 },
      { kind: "rent", periodIndex: 3, periodStart: "2026-04-30", periodEnd: "2026-05-30", dueDate: "2026-04-30", amountSen: 150_000 },
      { kind: "rent", periodIndex: 4, periodStart: "2026-05-31", periodEnd: "2026-06-29", dueDate: "2026-05-31", amountSen: 150_000 },
      { kind: "rent", periodIndex: 5, periodStart: "2026-06-30", periodEnd: "2026-07-15", dueDate: "2026-06-30", amountSen: 77_419 },
    ]);
  });

  it("Ben's lease: no deposit, last period rounds a .5 up (100029 x 15/30 = 50014.5)", () => {
    const schedule = generateSchedule(lease("2026-01-01", "2026-04-15", 100_029));
    expect(schedule.every((invoice) => invoice.kind === "rent")).toBe(true);
    expect(schedule.map((invoice) => invoice.periodIndex)).toEqual([0, 1, 2, 3]);
    expect(rentRows(lease("2026-01-01", "2026-04-15", 100_029))).toEqual([
      ["2026-01-01", "2026-01-31", "2026-01-01", 100_029],
      ["2026-02-01", "2026-02-28", "2026-02-01", 100_029],
      ["2026-03-01", "2026-03-31", "2026-03-01", 100_029],
      ["2026-04-01", "2026-04-15", "2026-04-01", 50_015],
    ]);
  });

  it("Probe's lease (Feb 28 start, ends the day before the 12th anchor) is 12 full periods", () => {
    const schedule = generateSchedule(lease("2026-02-28", "2027-02-27", 200_000, 400_000));
    expect(schedule[0]).toMatchObject({ kind: "deposit", dueDate: "2026-02-28", amountSen: 400_000 });
    const rows = rent(schedule);
    expect(rows).toHaveLength(12);
    expect(rows.every((invoice) => invoice.amountSen === 200_000)).toBe(true);
    expect(rows[1]).toMatchObject({ periodStart: "2026-03-28", periodEnd: "2026-04-27" });
    expect(rows[11]).toMatchObject({ periodIndex: 11, periodStart: "2027-01-28", periodEnd: "2027-02-27" });
  });

  it("Chen's lease (15th to 14th) is 12 full periods", () => {
    const rows = rent(generateSchedule(lease("2026-03-15", "2027-03-14", 220_000, 440_000)));
    expect(rows).toHaveLength(12);
    expect(rows.every((invoice) => invoice.amountSen === 220_000)).toBe(true);
    expect(rows[11]).toMatchObject({ periodStart: "2027-02-15", periodEnd: "2027-03-14" });
  });

  it("omits the deposit when it is 0", () => {
    expect(generateSchedule(lease("2026-01-01", "2026-01-31", 100_000, 0))).toEqual([
      { kind: "rent", periodIndex: 0, periodStart: "2026-01-01", periodEnd: "2026-01-31", dueDate: "2026-01-01", amountSen: 100_000 },
    ]);
  });

  it("counts anchors from the start date, clamped to month end, in a leap year (Jan 31, 2028)", () => {
    expect(rentRows(lease("2028-01-31", "2028-05-30")).map((row) => [row[0], row[1]])).toEqual([
      ["2028-01-31", "2028-02-28"],
      ["2028-02-29", "2028-03-30"],
      ["2028-03-31", "2028-04-29"],
      ["2028-04-30", "2028-05-30"],
    ]);
  });

  it("a lease starting on Feb 29 anchors on the 29th and clamps to Feb 28 the next year", () => {
    const rows = rentRows(lease("2028-02-29", "2029-02-27"));
    expect(rows).toHaveLength(12);
    expect(rows.map((row) => row[0])).toEqual([
      "2028-02-29",
      "2028-03-29",
      "2028-04-29",
      "2028-05-29",
      "2028-06-29",
      "2028-07-29",
      "2028-08-29",
      "2028-09-29",
      "2028-10-29",
      "2028-11-29",
      "2028-12-29",
      "2029-01-29",
    ]);
    expect(rows[11]).toEqual(["2029-01-29", "2029-02-27", "2029-01-29", 100_000]);
    // One more day reaches the clamped anchor 2029-02-28: a 1-day period of a 29-day month (Feb 28 -> Mar 28).
    const longer = rentRows(lease("2028-02-29", "2029-02-28", 290_000));
    expect(longer).toHaveLength(13);
    expect(longer[12]).toEqual(["2029-02-28", "2029-02-28", "2029-02-28", 10_000]);
  });

  it("a lease starting on the 30th clamps to Feb 28 and returns to the 30th", () => {
    expect(rentRows(lease("2026-01-30", "2026-04-29")).map((row) => [row[0], row[1]])).toEqual([
      ["2026-01-30", "2026-02-27"],
      ["2026-02-28", "2026-03-29"],
      ["2026-03-30", "2026-04-29"],
    ]);
  });

  it("a lease starting on the 29th in a non-leap year clamps to Feb 28", () => {
    expect(rentRows(lease("2027-01-29", "2027-03-28")).map((row) => [row[0], row[1]])).toEqual([
      ["2027-01-29", "2027-02-27"],
      ["2027-02-28", "2027-03-28"],
    ]);
  });

  it("a one-day lease (start == end) costs 1/full of the month", () => {
    // Full period 2026-03-10..2026-04-09 is 31 days.
    expect(rentRows(lease("2026-03-10", "2026-03-10", 310_000))).toEqual([
      ["2026-03-10", "2026-03-10", "2026-03-10", 10_000],
    ]);
    // Feb 2026 period (Feb 10..Mar 9) is 28 days: 100000 / 28 = 3571.43 -> 3571.
