describe("invoiceStatus", () => {
  const due = "2026-03-01";

  it("is paid when paidSen >= amountSen, even long after the due date", () => {
    expect(invoiceStatus({ dueDate: due, amountSen: 1000, paidSen: 1000 }, new Date("2027-01-01T00:00:00Z"))).toBe("paid");
    expect(invoiceStatus({ dueDate: due, amountSen: 1000, paidSen: 1500 }, new Date("2027-01-01T00:00:00Z"))).toBe("paid");
    expect(invoiceStatus({ dueDate: due, amountSen: 0, paidSen: 0 }, new Date("2027-01-01T00:00:00Z"))).toBe("paid");
  });

  it("is not overdue until 00:00 Malaysia time the day after the due date", () => {
    const unpaid = { dueDate: due, amountSen: 1000, paidSen: 0 };
    expect(invoiceStatus(unpaid, new Date("2026-03-01T15:59:59.999Z"))).toBe("unpaid");
    expect(invoiceStatus(unpaid, new Date("2026-03-01T16:00:00.000Z"))).toBe("overdue");
    expect(invoiceStatus(unpaid, new Date("2026-02-28T16:00:00.000Z"))).toBe("unpaid"); // Mar 1 00:00 MYT
    expect(invoiceStatus(unpaid, new Date("2026-02-28T15:59:59.999Z"))).toBe("unpaid");
  });

  it("overdue beats partially_paid; partially_paid before the deadline", () => {
    const partial = { dueDate: due, amountSen: 1000, paidSen: 1 };
    expect(invoiceStatus(partial, new Date("2026-03-01T15:59:59.999Z"))).toBe("partially_paid");
    expect(invoiceStatus(partial, new Date("2026-03-01T16:00:00.000Z"))).toBe("overdue");
    expect(invoiceStatus({ dueDate: due, amountSen: 1000, paidSen: 999 }, new Date("2026-03-05T00:00:00Z"))).toBe("overdue");
  });

  it("uses the Malaysia date across a year boundary", () => {
    const invoice = { dueDate: "2026-12-31", amountSen: 1000, paidSen: 0 };
    expect(invoiceStatus(invoice, new Date("2026-12-31T15:59:59.999Z"))).toBe("unpaid");
    expect(invoiceStatus(invoice, new Date("2026-12-31T16:00:00.000Z"))).toBe("overdue");
  });

  it("throws on an invalid Date or due date", () => {
    expect(() => invoiceStatus({ dueDate: due, amountSen: 1000, paidSen: 0 }, new Date("nope"))).toThrow();
    expect(() => invoiceStatus({ dueDate: "2026-02-30", amountSen: 1000, paidSen: 0 }, new Date())).toThrow();
  });
});

